// CSD_RATIONALE_BEGIN
// Root cause of all recent regressions (2–10% accuracy):
// With correct RenderedEndsWith detection, every model-generated "<<" triggers
// constrained mode. The model writes ~15 spans per example (avg 1.09 tokens/span)
// because parser.IsCompletePrefix fires on SINGLE-TOKEN names like <<n>>, <<frac>>,
// <<k>>, and we close immediately. The LAST span extracted is a single variable, not
// the full combined answer.
//
// Fix: Add minimum expression length (minExprLen = 5) before allowing
// CloseConstrainedSpan to fire. When IsCompletePrefix is true but |currentConstrainedOut| < 5,
// we continue constrained generation. The hard mask from AdaptiveConstrainedStep then
// returns operators (+, -, *, /) which the LM prefers in context, forcing the span to
// grow into a multi-term expression like <<n * k * (12 // m)>> before closing.
// Budget pressure is handled by CloseSpanWithinBudget in the final 5 steps.
//
// Guidance: explicitly show WRONG (operators between spans) vs RIGHT (full expression
// inside ONE span) to address the second failure mode where the model writes
// <<a>> + <<b>> with operators between spans.
//
// This is a minimal surgical change from the best attempt structure (Attempt 1) while
// correcting the RenderedEndsWith usage that triggered the regression.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside branch (UnconstrainedStep):
//     EOS path: break; insideConstrainedOut unchanged (false); implication vacuous. ✓
//     Non-EOS, RenderedEndsWith fires: EnterObservedConstrainedSpan sets
//       currentConstrainedOut := []; parser.IsValidPrefix([]) by precondition. ✓
//     Non-EOS, RenderedEndsWith does not fire: insideConstrainedOut stays false;
//       implication vacuous. ✓
//
//   Inside branch, CloseConstrainedSpan (guarded by IsCompletePrefix && |cc|>=5):
//     Precondition parser.IsCompletePrefix(currentConstrainedOut) is checked before call.
//     Helper sets insideConstrainedOut := false → implication vacuously true;
//     sets currentConstrainedOut := []. ✓
//
//   Inside branch, CloseSpanWithinBudget:
//     Helper postcondition directly ensures
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   Inside branch, AdaptiveConstrainedStep + AppendConstrainedToken:
//     EOS path: break; insideConstrainedOut unchanged; currentConstrainedOut unchanged
//       (still valid from loop invariant). ✓
//     Non-EOS: AdaptiveConstrainedStep hard-masks to parser-valid next tokens.
//       AppendConstrainedToken extends currentConstrainedOut by the valid token,
//       preserving parser.IsValidPrefix. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: generated = generatedPrefix, steps = 0. Holds trivially.
//
//   Outside, non-EOS: steps += 1, |generated| grows by exactly 1 token.
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//   Outside, EOS: steps += 1, |generated| unchanged.
//     |generated| <= |generatedPrefix| + steps_old < |generatedPrefix| + steps_new. ✓
//
//   CloseConstrainedSpan: steps += 1, |cg| <= |generated| + 1 (the ">>" delimiter).
//     |generated|_new <= |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//
//   CloseSpanWithinBudget (closeBudget = maxSteps - steps_old):
//     Helper guarantees |cg| <= |generated| + closeBudget.
//     After steps := maxSteps:
//     |generated| <= |generatedPrefix| + steps_old + (maxSteps - steps_old)
//               = |generatedPrefix| + maxSteps = |generatedPrefix| + steps_new. ✓
//
//   AdaptiveConstrainedStep, non-EOS: steps += 1; AppendConstrainedToken appends 1 token.
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + steps_new. ✓
//   AdaptiveConstrainedStep, EOS: steps += 1; generated unchanged.
//     |generated| <= |generatedPrefix| + steps_old < |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. When writing << >> spans, ALWAYS include a COMPLETE combined arithmetic expression inside the span. WRONG: <<a>> * <<b>> (operators between spans). RIGHT: <<a * b>> (full expression inside one span). The last << >> span is the extracted answer, so the final << >> must contain the COMPLETE combined formula for the answer.");

var steps: nat := 0;
var narrowThreshold: nat := 12;
var minExprLen: nat := 5;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := eg;
        insideConstrainedOut := ei;
        currentConstrainedOut := ec;
      }
    }
  } else {
    if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minExprLen {
      // Span has a complete parse with sufficient content: close it.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 5 {
      // Near budget end: use budget-bounded close to finish gracefully.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Continue constrained generation (extend short/incomplete expression).
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

